'use client';

import React, { useMemo, useEffect } from 'react';
import { useFinanceiro } from '../context/FinanceiroContext';
import { theadClass } from '../_components/shared';
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from '@/components/ui/table';
import { COLORS, ProductSelect, withAlpha, ELEVATION } from '@/design-system';
import { HistoricoPeriodFilterBar } from './HistoricoPeriodFilterBar';
import { HistoricoDesembolsoChart } from './HistoricoDesembolsoChart';
import type { HistoricoChartTooltipProps } from './HistoricoDesembolsoChart';
import {
    HistoricoTooltipMetas,
    HistoricoTooltipRow,
    HistoricoTooltipShell,
} from './HistoricoChartTooltip';
import {
    FechamentoMetaChips,
    FechamentoMetricTile,
    FechamentoStatusBadge,
    fechamentoStatusTone,
} from './HistoricoFechamentoUI';
import { 
    Calendar, 
} from 'lucide-react';

// Helper functions for month range calculations
function getMonthsRange(startKey: string, endKey: string): string[] {
    if (!startKey || !endKey) return [];
    const [startM, startY] = startKey.split('/').map(Number);
    const [endM, endY] = endKey.split('/').map(Number);

    const range: string[] = [];
    let curY = startY;
    let curM = startM;

    while (curY < endY || (curY === endY && curM <= endM)) {
        range.push(`${String(curM).padStart(2, '0')}/${curY}`);
        curM++;
        if (curM > 12) {
            curM = 1;
            curY++;
        }
    }
    return range;
}

// Get relative month key based on offset
function getRelativeMonth(monthKey: string, offset: number): string {
    const [m, y] = monthKey.split('/').map(Number);
    const date = new Date(y, m - 1 + offset, 1);
    return `${String(date.getMonth() + 1).padStart(2, '0')}/${date.getFullYear()}`;
}

